// Find a free block using lookahead buffer with wear leveling
lfs_block_t block = 0xffffffff;
int err = 0;

// Check if we need to refresh the lookahead buffer
if (lfs->lookahead.off == lfs->lookahead.size) {
    lfs->lookahead.off = 0;
    lfs->lookahead.size = lfs_min(lfs->cfg->lookahead_size, lfs->block_count);

    // Find the next free block using lookahead
    while (true) {
        // Scan for free blocks in lookahead window
        lfs_block_t start = lfs->lookahead.start;
        lfs_block_t end = (start + lfs->lookahead.size) % lfs->block_count;

        for (lfs_block_t i = 0; i < lfs->lookahead.size; i++) {
            lfs_block_t candidate = (start + i) % lfs->block_count;

            // Check if block is free using lookahead buffer
            lfs_block_t off = ((candidate - lfs->lookahead.start) + lfs->block_count) % lfs->block_count;
            if (off < lfs->lookahead.size) {
                uint8_t *buffer = (uint8_t*)lfs->lookahead.buffer;
                if (!(buffer[off / 8] & (1 << (off % 8)))) {
                    block = candidate;
                    break;
                }
            }
        }

        if (block != 0xffffffff) {
            break;
        }

        // No free blocks found, move lookahead window
        lfs->lookahead.start = (lfs->lookahead.start + lfs->lookahead.size) % lfs->block_count;

        // Check if we've wrapped around (no space)
        if (lfs->lookahead.start == 0) {
            return LFS_ERR_NOSPC;
        }
    }
} else {
    // Use existing lookahead buffer
    while (lfs->lookahead.off < lfs->lookahead.size) {
        lfs_block_t candidate = (lfs->lookahead.start + lfs->lookahead.off) % lfs->block_count;
        lfs_block_t off = ((candidate - lfs->lookahead.start) + lfs->block_count) % lfs->block_count;

        if (off < lfs->lookahead.size) {
            uint8_t *buffer = (uint8_t*)lfs->lookahead.buffer;
            if (!(buffer[off / 8] & (1 << (off % 8)))) {
                block = candidate;
                break;
            }
        }
        lfs->lookahead.off++;
    }

    if (block == 0xffffffff) {
        return LFS_ERR_NOSPC;
    }
}

// Mark block as used in lookahead buffer
lfs_block_t off = ((block - lfs->lookahead.start) + lfs->block_count) % lfs->block_count;
if (off < lfs->lookahead.size) {
    uint8_t *buffer = (uint8_t*)lfs->lookahead.buffer;
    buffer[off / 8] |= (1 << (off % 8));
}

// Update lookahead offset for next allocation
lfs->lookahead.off++;

// Update wear leveling - move start forward for next allocation
lfs->lookahead.start = (lfs->lookahead.start + 1) % lfs->block_count;

*block = block;
return 0;
